@startuml

class Customer {
  + headOfficeAddress : string
  + vatNumber : string
}

class Address {
  + location : string
}

class Product {
  + name : string
  + stockLevel : int
}

class Order {
  + orderDate : date
  + paidDate : date
  + isFullyPaid : boolean
}

class OrderLine {
  + quantity : int
  + isShipped : boolean
}

class Invoice {
  + invoiceDate : date
  + isPaid : boolean
}

class Shipment {
  + status : string
}

class DeliveryService {
  + name : string
}

Customer "1" -- "*" Address : headOfficeAddress
Customer "1" -- "*" Order : places
Customer "1" -- "*" Invoice : receives
Customer "1" -- "*" Address : deliveryAddress
Order "1" *-- "1..*" OrderLine : contains
Order "1" -- "0..1" Invoice : generates
OrderLine "*" -- "1" Product : refers to
Shipment "*" -- "1" DeliveryService : uses
Shipment "*" -- "1..*" OrderLine : contains
Shipment "1" -- "1" Address : delivers to

@enduml

